use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(index: i) {
            Some(plank) => {
                if rules.keeps(plank: plank) {
                    labels.push(item: rules.label(plank: plank));
                };
                unit
            },
            None => unit,
        };
        i = i + 1;
    }
    labels.join(sep: ",")
}

