use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Ok(n) => n,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    return relay.feed.emit(io: io, total: total);
}

use harbor.signal;

fn render(signal: Signal) -> String {
    match signal {
        Calm => "calm",
        Gale(speed) => "gale:".concat(other: speed.to_text()),
        Fog(density) => "fog:".concat(other: density),
    }
}

pub fn entries() -> String {
    let signals = sequence();
    var parts: List<String> = [];
    var i = 0;
    while i < signals.len() {
        let s = signals.get(index: i)?;
        parts.push(item: render(signal: s));
        i = i + 1;
    }
    parts.join(sep: ";")
}

